#include <stdio.h>
#include <string.h>
void reverse(char *s) {
    char *left = s;
    char *right = s + strlen(s) - 1;
    while (left < right) {
        char saved = *left;
        *left++ = *right;
        *right-- = saved;
    }
}
int main(void) {
    char value[] = "ABCDEFGH";
    reverse(value);
    int length = (int)strlen(value);
    for (int i = 1; i < length; i += 2) {
        printf("%c", value[i]);
    }
    return 0;
}

class Parent {
    int x, y;
    Parent(int x, int y) { // ①
        this.x = x;
        this.y = y;
    }
    int getT() { // ②
        return x * y;
    }
}
class Child extends Parent {
    int x;
    Child(int x) { // ③
        super(x + 1, x);
        this.x = x;
    }
    int getT(int n) { // ④
        return super.getT() + n;
    }
}
class Main {
    public static void main(String[] args) { // ⑤
        Parent parent = new Child(3); // ⑥
        System.out.println(parent.getT()); // ⑦
    }
}

#include <stdio.h>
struct Account { int number; double balance; };
