#include <stdio.h>
int main(void) {
    char value[] = "It is 8";
    for (int i = 0; value[i] != '\0'; ++i) {
        char c = value[i];
        if (c >= 'A' && c <= 'Z') {
            value[i] = 'A' + (c - 'A' + 5) % 25;
        } else if (c >= 'a' && c <= 'z') {
            value[i] = 'a' + (c - 'a' + 10) % 26;
        } else if (c >= '0' && c <= '9') {
            value[i] = '0' + (c - '0' + 3) % 10;
        }
    }
    printf("%s", value);
    return 0;
}
